        CardExpiration: DateTime.UtcNow.AddYears(1),
        CardSecurityNumber: "111",
        CardTypeId: checkoutInfo.CardTypeId,
        Buyer: buyerId,
        Items: [.. orderItems]);
    await orderingService.CreateOrder(request, checkoutInfo.RequestId);
    await DeleteBasketAsync();
}

