2	
3	/// <summary>
4	/// Provides a base implementation for handling duplicate request and ensuring idempotent updates, in the cases where
5	/// a requestid sent by client is used to detect duplicate requests.
6	/// </summary>
7	/// <typeparam name="T">Type of the command handler that performs the operation if request is not duplicated</typeparam>
8	/// <typeparam name="R">Return value of the inner command handler</typeparam>
9	public abstract class IdentifiedCommandHandler<T, R> : IRequestHandler<IdentifiedCommand<T, R>, R>
10	    where T : IRequest<R>
11	{
12	    private readonly IMediator _mediator;
13	    private readonly IRequestManager _requestManager;
14	    private readonly ILogger<IdentifiedCommandHandler<T, R>> _logger;
15	
16	    public IdentifiedCommandHandler(
17	        IMediator mediator,
18	        IRequestManager requestManager,
19	        ILogger<IdentifiedCommandHandler<T, R>> logger)
20	    {
21	        ArgumentNullException.ThrowIfNull(logger);
22	        _mediator = mediator;
23	        _requestManager = requestManager;
24	        _logger = logger;
25	    }
26	
27	    /// <summary>
28	    /// Creates the result value to return if a previous request was found
29	    /// </summary>
30	    /// <returns></returns>
31	    protected abstract R CreateResultForDuplicateRequest();
32	
33	    /// <summary>
34	    /// This method handles the command. It just ensures that no other request exists with the same ID, and if this is the case
35	    /// just enqueues the original inner command.
36	    /// </summary>
37	    /// <param name="message">IdentifiedCommand which contains both original command & request ID</param>
38	    /// <returns>Return value of inner command or default value if request same ID was found</returns>
39	    public async Task<R> Handle(IdentifiedCommand<T, R> message, CancellationToken cancellationToken)
40	    {
41	        var alreadyExists = await _requestManager.ExistAsync(message.Id);
42	        if (alreadyExists)
43	        {
44	            return CreateResultForDuplicateRequest();
45	        }
46	        else
47	        {
48	            await _requestManager.CreateRequestForCommandAsync<T>(message.Id);
49	            try
50	            {
51	                var command = message.Command;
52	                var commandName = command.GetGenericTypeName();
53	                var idProperty = string.Empty;
54	                var commandId = string.Empty;
55	
56	                switch (command)
57	                {
58	                    case CreateOrderCommand createOrderCommand:
59	                        idProperty = nameof(createOrderCommand.UserId);
60	                        commandId = createOrderCommand.UserId;
61	                        break;
62	
63	                    case CancelOrderCommand cancelOrderCommand:
64	                        idProperty = nameof(cancelOrderCommand.OrderNumber);
65	                        commandId = $"{cancelOrderCommand.OrderNumber}";
66	                        break;
67	
68	                    case ShipOrderCommand shipOrderCommand:
69	                        idProperty = nameof(shipOrderCommand.OrderNumber);
70	                        commandId = $"{shipOrderCommand.OrderNumber}";
71	                        break;
72	
73	                    default:
74	                        idProperty = "Id?";
75	                        commandId = "n/a";
76	                        break;
77	                }
78	
79	                _logger.LogInformation(
80	                    "Sending command: {CommandName} - {IdProperty}: {CommandId} ({@Command})",
81	                    commandName,
82	                    idProperty,
83	                    commandId,
84	                    command);
85	
86	                // Send the embedded business command to mediator so it runs its related CommandHandler 
87	                var result = await _mediator.Send(command, cancellationToken);
88	
89	                _logger.LogInformation(
90	                    "Command result: {@Result} - {CommandName} - {IdProperty}: {CommandId} ({@Command})",
91	                    result,
92	                    commandName,
93	                    idProperty,
94	                    commandId,
95	                    command);
96	
97	                return result;
98	            }
99	            catch
100	            {
101	                return default;
102	            }
103	        }
104	    }
105	}
